//! 📦️ Native boxed output retains real typed backing before its separately funded payload initialization.
use super::{NativeReceive,NativeReceiver,NativeDecodeControl,RetainedCloneRef};
use crate::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneClose,retained_clone_grant_admits}};
use semio_framework_value_native_storage::NativeOwnedStorage;
use std::{mem::ManuallyDrop,marker::PhantomData};
pub struct NativeBoxReceiver<I:?Sized+'static,T:NativeReceive<I>>{inner:T::Receiver,pending:ManuallyDrop<Option<T>>,pending_box:ManuallyDrop<Option<Box<T>>>,backing:NativeOwnedStorage<T>,retirement:RetainedCloneClose,closing:bool,marker:PhantomData<fn(&I)>}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"native boxed receiver has no funded owner in the required phase")}
fn control()->RetirementDemand{RetirementDemand{depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand)->Result<RetirementDemand,ValueError>{d.depth=d.depth.checked_add(1).ok_or_else(invalid)?;Ok(d)}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g}}
impl<I:?Sized+'static,T:NativeReceive<I>> NativeBoxReceiver<I,T>{pub fn new()->Self{Self{inner:T::receiver(),pending:ManuallyDrop::new(None),pending_box:ManuallyDrop::new(None),backing:NativeOwnedStorage::empty(),retirement:Default::default(),closing:false,marker:PhantomData}}}
impl<I:?Sized+'static,T:NativeReceive<I>> NativeReceiver<I,Box<T>> for NativeBoxReceiver<I,T>{
 fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.backing.initialized(){return Err(invalid())}if self.pending.is_some(){return Ok(if self.backing.reserved(){NativeOwnedStorage::<T>::move_demand()}else{NativeOwnedStorage::<T>::reserve_demand()})}nested(if self.inner.output_ready(){self.inner.take_demand()?}else{self.inner.demands(input,body)?})}
 fn advance(&mut self,input:RetainedCloneRef<'_,I>,decode:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,crate::OriginalReceivingPrimary>{let mut work=0;let result:Result<RetainedCloneStep,crate::OriginalReceivingPrimary>=(||{let d=self.demands(input,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}decode.checkpoint()?;crate::owned::receiving_capacity(decode,d.capacity_bytes)?;if self.pending.is_some(){let turn=if self.backing.reserved(){self.backing.put_from(&mut self.pending,g)}else{self.backing.reserve(g)};let turn=decode.receive_retained_work(g,turn);work=turn.work;return turn.result.map_err(Into::into)}if self.inner.output_ready(){let turn=self.inner.take(child(g));work=turn.work;let Some((value,p))=turn.result?else{return Ok(RetainedCloneStep::Progress(Default::default()))};*self.pending=Some(value);return Ok(RetainedCloneStep::Progress(p))}let turn=self.inner.advance(input,decode,body,child(g));work=turn.work;turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into)})();RetainedWorkOutcome{result,work}}
 fn output_ready(&self)->bool{!self.closing&&self.backing.initialized()}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid())}Ok(control())}
 fn take(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome<Option<(Box<T>,RetainedCloneProgress)>>{if !self.output_ready(){return RetainedWorkOutcome{result:Err(invalid()),work:0}}self.backing.take_box(g)}
 fn begin_close(&mut self){self.closing=true;self.inner.begin_close()}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.inner.terminal_is_empty(){return nested(self.inner.close_demands(body)?)}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<T>(false,&None,body)}if self.pending_box.is_some(){return self.retirement.next_owner_demands::<Box<T>>(true,&None,body)}if self.pending.is_some(){return self.retirement.next_owner_demands::<T>(true,&None,body)}if self.backing.initialized(){return Ok(control())}Ok(self.backing.release_demand())}
 fn close_step(&mut self,g:RetainedCloneGrant)->crate::OriginalRetirementOutcome{let mut work=0;let result:Result<RetainedCloneStep,crate::OriginalRetirementFailure>=(||{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.inner.terminal_is_empty(){let turn=self.inner.close_step(child(g));work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into)}if !self.retirement.is_empty(){let turn=self.retirement.step_granted(g);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}if self.pending_box.is_some(){let turn=self.retirement.begin_granted(&mut self.pending_box,g);work=turn.work;return turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)}if self.pending.is_some(){let turn=self.retirement.begin_granted(&mut self.pending,g);work=turn.work;return turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)}if self.backing.initialized(){let turn=self.backing.take_box(g);work=turn.work;let Some((value,p))=turn.result?else{return Ok(RetainedCloneStep::Progress(Default::default()))};*self.pending_box=Some(value);return Ok(RetainedCloneStep::Progress(p))}let turn=self.backing.release(g);work=turn.work;turn.result.map_err(Into::into)})();RetainedWorkOutcome{result,work}}
 fn terminal_is_empty(&self)->bool{self.inner.terminal_is_empty()&&self.pending.is_none()&&self.pending_box.is_none()&&self.backing.terminal_is_empty()&&self.retirement.is_empty()}
}
impl<I:?Sized+'static,T:NativeReceive<I>> Drop for NativeBoxReceiver<I,T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native boxed receiver retains its actual typed owners");}}
impl<I:?Sized+'static,T:NativeReceive<I>> NativeReceive<I> for Box<T>{type Receiver=NativeBoxReceiver<I,T>;fn receiver()->Self::Receiver{NativeBoxReceiver::new()}}
